from __future__ import division

from abc import ABCMeta, abstractmethod, abstractproperty
from collections import namedtuple

import requests
from lxml import etree
from six import add_metaclass
from tqdm import tqdm

from hran_pacman.bases.base import DownloaderBase
from hran_pacman.bases.logger import LOGGER
from hran_pacman.exceptions import InvalidBuildException, NetworkException

File = namedtuple("File", ["name", "url"])


def _test_url(url):
    try:
        response = requests.head(url, timeout=3)
        accessible = response.status_code == 200
        LOGGER.debug("Status: {}".format(response.status_code))
    except requests.RequestException as exc:
        accessible = False
        LOGGER.debug("{} occurred while accessing {}".format(exc.__class__.__name__, url))
    return accessible


def _is_file_accessible(f):
    LOGGER.info("Checking package accessibility at {}".format(f.url))
    accessible = _test_url(f.url)
    LOGGER.info("Package {}accessible at {}".format("" if accessible else "not ", f.url))
    return accessible


@add_metaclass(ABCMeta)
class WFTDownloader(DownloaderBase):
    build_info_url_base = "https://wft.int.net.nokia.com/ext/build_content/{baseline}?skip_cache=true"
    sem_url_base = (
        "https://wft.int.net.nokia.com:8091/"
        "secure_download/load_zip/{version}"
        "/4?access_key=QF5oQmJRkaK4UWIDMGH0Ore6RcQMzseZ459IdCIB"
    )
    _build_info = None

    def __init__(self, baseline, api_key=None, turbo_mode=False):
        """
        Package downloader for LTE
        :param baseline: package baseline
        """
        super(WFTDownloader, self).__init__(baseline, api_key, turbo_mode=turbo_mode)
        self.api_key = api_key

    def _get_build_info(self):
        try:
            return etree.fromstring(self._get_build_info_content())
        except etree.XMLSyntaxError:
            url = self.build_info_url_base.format(baseline=self.baseline)
            raise InvalidBuildException("Could not parse content. " "Please, verify url content: {}".format(url))

    def _get_build_info_content(self):
        url = self.build_info_url_base.format(baseline=self.baseline)
        LOGGER.debug(url)
        try:
            response = requests.get(url, verify=False)
        except requests.exceptions.RequestException as exc:
            raise NetworkException("Network exception occured [{}]: {}".format(exc.__class__.__name__, str(exc)))
        if not response.content:
            raise InvalidBuildException("Could not get build info")
        return response.content

    @property
    def site_manager_baseline(self):
        """
        Baseline of BTS Site Manager associated with current package baseline
        :return: BTSSM baseline
        """
        component = self.build_info.find('.//baseline[@sc="BTS Site Manager"]')
        if component is None:
            raise InvalidBuildException("Could not determine Site Manager baseline")
        return component.text

    @property
    def build_info(self):
        """
        Build info XML
        :return: parsed build info document
        """
        if self._build_info is None:
            self._build_info = self._get_build_info()
        return self._build_info

    @property
    @abstractproperty
    def downloadable_name(self):
        """
        Pattern to filter downloadables by
        """

    def get_software_package(self):
        """
        Method downloads software package to current working directory
        """
        package = self.get_downloadable_file()
        header = {'X-JFrog-Art-Api': self.api_key}
        data = requests.get(package.url, headers=header, stream=True)
        self._stream_to_file(self.package_name, data)

    def get_downloadable_file(self):
        """
        Returns downloadable file representation
        :return: downloadable file
        """
        LOGGER.info("Checking accessibility of %s" % self.downloadable_name)
        valid_files = (_file for _file in self.files if self._file_is_valid(_file))
        package = next(valid_files, None)
        if package is None:
            raise InvalidBuildException("Did not found downloadable " "file for name %s" % self.downloadable_name)
        return package

    def _stream_to_file(self, filename, data, chunk_size=4096, iterations=10, assumed_file_size=524288000):
        data_size = int(data.headers.get("content-length", "0"))
        desc_template = "< using assumed file size => {}mb >"
        desc = desc_template.format(int(assumed_file_size / (1024 * 1024))) if not data_size else ""
        pbar = tqdm(total=data_size, unit="B", unit_scale=True, desc=desc)
        self._save_package(chunk_size, data, data_size, filename, iterations, pbar)
        LOGGER.info("File downloading finished")

    def _save_package(self, chunk_size, data, data_size, filename, iterations, progress_bar):
        iterations = iterations or 1
        collected = 0
        with open(filename, "wb") as file_:
            for chunk in data.iter_content(chunk_size=chunk_size):
                file_.write(chunk)
                collected += chunk_size
                collected = self._update_progress_bar(collected, data_size, iterations, progress_bar)

    def _update_progress_bar(self, collected, data_size, iterations, pbar):
        if collected > (data_size / iterations):
            pbar.update(collected)
            collected = 0
        return collected

    @property
    def files(self):
        """
        List of files found in build info
        :return: list of files
        """
        return [File(item.attrib.get("title"), item.attrib.get("url")) for item in self.build_info.xpath("//file")]

    @abstractmethod
    def get_site_manager(self):
        """
        Method downloads BTS Site Manager to current working directory
        """

    def _file_is_valid(self, _file):
        """
        Checks if given is a proper candidate for download and can be accessed
        :param _file: file representation
        :type file: File
        :return: if file has a proper name and can be downloaded
        """
        return self._is_file_matching_downloadable_name(_file) and _is_file_accessible(_file)

    def _is_file_matching_downloadable_name(self, _file):
        return self.downloadable_name in _file.name
